<?php declare(strict_types=1);$base=config('app.base_path');$trash=!empty($trash); ?><div class="page-header"><div><h1><?= $trash?'Deleted Tourism Providers':'Tourism Providers' ?></h1><p><?= $trash?'Restore providers moved to Trash.':'Local hotels, homestays, resorts, lodges and tourism operators.' ?></p></div><div class="page-actions"><?php if($trash): ?><a class="btn btn-secondary" href="<?= $base ?>/tourism/providers">Active Providers</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/tourism/providers?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/tourism/providers/create">Add Provider</a><?php endif; ?></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Provider</th><th>Type</th><th>Location</th><th>Coordinates</th><th>Stays</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(empty($providers)): ?><tr><td colspan="7"><div class="empty-state">No tourism providers found.</div></td></tr><?php else: foreach($providers as $p): ?><tr><td><strong><?= htmlspecialchars((string)$p['business_name'],ENT_QUOTES,'UTF-8') ?></strong><br><small><?= htmlspecialchars((string)($p['phone']??''),ENT_QUOTES,'UTF-8') ?></small></td><td><?= htmlspecialchars((string)$p['provider_type'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars((string)($p['business_city']??''),ENT_QUOTES,'UTF-8') ?><br><small><?= htmlspecialchars((string)($p['business_district']??''),ENT_QUOTES,'UTF-8') ?></small></td><td><?= $p['latitude']!==null?htmlspecialchars($p['latitude'].' , '.$p['longitude'],ENT_QUOTES,'UTF-8'):'Not set' ?></td><td><?= (int)$p['stay_count'] ?></td><td><?= htmlspecialchars((string)$p['status'],ENT_QUOTES,'UTF-8') ?></td><td><?php if($trash): ?><form method="post" action="<?= $base ?>/tourism/providers/<?= (int)$p['id'] ?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/tourism/providers/<?= (int)$p['id'] ?>">View</a> <a class="link-button" href="<?= $base ?>/tourism/providers/<?= (int)$p['id'] ?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
